SELECT COALESCE(SUM(amount), 0)
FROM payment_record
WHERE payment_target_type = #{paymentTargetType}
AND target_id = #{targetId}
AND record_status = 'CONFIRMED'

SELECT EXISTS (
SELECT 1
FROM payment_record
WHERE bank_transaction_id = #{bankTransactionId}
)

SELECT payment_record_id AS paymentRecordId, bank_transaction_id AS bankTransactionId, payment_target_type AS paymentTargetType, target_id AS targetId, amount, source_type AS sourceType, record_status AS recordStatus, recorded_at AS recordedAt, cancelled_by_id AS cancelledById, cancelled_at AS cancelledAt, memo FROM payment_record WHERE payment_target_type = #{paymentTargetType} AND target_id IN
#{targetId}
AND record_status = 'CONFIRMED' ORDER BY recorded_at DESC
